/* Purview Gurukul — Specialties: the Behavioral health and IOP track.
   Built from two reference documents shared in November 2026: the "UB-04 & IOP" training module
   (institutional billing, the UB-04, IOP revenue, HCPCS and diagnosis codes, modifiers, the claim
   lifecycle, AR cleanup, and Medicare IOP for RHCs and FQHCs under CR 13264) and a Kentucky behavioral
   health billing operations guide, version 2.0 (dual-diagnosis and IOP billing), used as reference
   material only: the provider it was written for is not a Purview client and is not named here.
   Where the two disagree, the newer, payer-checked guide is followed and the difference is noted; a
   few code descriptions in the module were corrected against HCPCS, CPT, NUBC and CMS. No provider
   names, addresses, contacts or rates are reproduced.
   Loaded after spec-dental.js; it adds one track to SPEC_TRACKS and its questions to SPEC_QUIZ. */
"use strict";
(function(){
if(typeof SPEC_TRACKS==="undefined"||typeof SPEC_QUIZ==="undefined") return;

const SRC="UB-04 & IOP training module and a Kentucky behavioral health billing operations guide v2.0 (November 2026, reference material), checked against CPT, HCPCS, NUBC revenue codes, CMS CR 13264 and the Kentucky MCO policies the guide cites.";
const SRC_KY="Kentucky behavioral health billing operations guide v2.0 (November 2026, reference material): Kentucky DMS, Aetna Better Health of Kentucky and Passport by Molina IOP policies as cited there. A payer’s contract or newer bulletin always overrides it.";

SPEC_TRACKS.push(
{id:"bh",name:"Behavioral health and IOP",short:"Behavioral health",updated:"UB-04 & IOP module and a Kentucky behavioral health billing guide v2.0, November 2026",
 truth:"The guide is the starting point; the client’s written confirmation and the payer’s current policy decide any rule on a claim. Items the guide marks CONFIRM are never guessed.",
 blurb:"Behavioral health covers mental health and substance use treatment. This track teaches what a biller needs for it: the words in the notes (levels of care, therapies, credentials, 42 CFR Part 2), the diagnosis and service codes, intensive outpatient programs (IOP) billed per diem on the UB-04 or CMS-1500, Medicare’s IOP rules, prior authorization, telehealth, denials and AR, and Kentucky Medicaid’s IOP rules as a worked example of a state program. It is not a clinical course.",
 modules:[
{id:"bh-a",short:"BH basics",title:"Behavioral health basics",blurb:"Conditions, levels of care, therapies, clinician credentials, the paperwork a biller reads, and the privacy rules for substance use records.",lessons:[
 {id:"bh-terms",title:"Behavioral health words: conditions, levels of care and therapies",
  keywords:["behavioral health","behavioural health","what is behavioral health","mental health billing","substance use disorder","what is sud","sud","dual diagnosis","co-occurring","co occurring disorders","asam","asam levels","levels of care","level of care","what is iop","intensive outpatient program","partial hospitalization","php","residential treatment","cbt","dbt","emdr","motivational interviewing","psychoeducation","peer support","case management","mat","medication assisted treatment","relapse prevention","treatment plan","progress note","attendance record","continued stay review","intake assessment","discharge summary"],
  line:"Behavioral health means mental health conditions and substance use disorders (SUD); a patient with both has a dual diagnosis (co-occurring disorders). Treatment is sorted into levels of care, from outpatient through intensive outpatient (IOP, ASAM level 2.1) and partial hospitalization (2.5) to residential, and the payer approves only the level the patient’s condition supports. The notes a biller reads (assessment, ASAM assessment, treatment plan, progress notes, attendance) are the proof that a billed service happened.",
  body:[
   "**Conditions.** Mental health (MH) conditions affect mood, thinking and behavior: depression, anxiety, PTSD, bipolar disorder. A **substance use disorder (SUD)** is continued use of alcohol or drugs despite harm; billing uses this term rather than “addiction”. A patient with both has **co-occurring disorders** or a **dual diagnosis**, and many programs treat both together. **Relapse** is a return to use after recovery; relapse prevention teaches the skills to avoid it.",
   "**Levels of care (ASAM).** The American Society of Addiction Medicine criteria sort SUD treatment by intensity: **level 1, outpatient** (short visits once or twice a week); **level 2.1, intensive outpatient (IOP)** (several hours a day, several days a week, living at home); **level 2.5, partial hospitalization (PHP)** (most of the day, home at night, billed differently from IOP); **level 3 and up, residential or inpatient** (overnight stay). Payers approve and continue IOP against these criteria, so the authorization request must support the level asked for.",
   "**Therapies you will see in notes.** Individual, group and family therapy; **CBT** (changing harmful thought patterns); **DBT** (skills for strong emotions); **EMDR** (processing painful memories with guided eye movements, billed as an ordinary therapy session); **motivational interviewing**; **psychoeducation** (teaching patients about their condition); **crisis intervention**; **peer support** (help from a certified person in recovery); **case management** (housing, medical care, other services); **medication management** (prescribers only); and **MAT**, medication-assisted treatment, where whoever prescribes the medicine bills for it.",
   "**The paperwork, and why billers care.** The **intake or assessment** shows the diagnosis and starts the authorization request; the **ASAM assessment** sets the level of care; the **treatment plan** must exist before IOP days are billed; each **progress note** proves a service happened and must be signed; the **group note and attendance record** with start and stop times prove the daily hours IOP needs; a **continued-stay review** extends an authorization; the **discharge summary** closes the episode."
  ],
  compare:{title:"Levels of care, lightest to most intense",head:["ASAM level","Name","What it means","Billing note"],rows:[["1","Outpatient (OP)","Short visits, once or twice a week","Session codes: therapy, counseling"],["2.1","Intensive outpatient (IOP)","Several hours a day, several days a week, at home at night","Per diem: H0015 or S9480; revenue code 0905 or 0906 on a UB-04"],["2.5","Partial hospitalization (PHP)","Most of the day, home at night","A different level: H0035, revenue code 0912 or 0913; never used for IOP"],["3 and up","Residential or inpatient","Overnight stay at the facility","Residential per diems; other behavioral codes on the same day deny as duplicative"]]},
  terms:[["SUD","Substance use disorder: continued use of alcohol or drugs despite harm."],["Dual diagnosis","A mental health condition and an SUD in the same patient, also called co-occurring disorders."],["ASAM","American Society of Addiction Medicine; its criteria set the levels of care payers authorize."],["IOP","Intensive outpatient program, ASAM level 2.1: structured treatment several hours a day, several days a week."],["Treatment plan","The patient’s goals and planned services; it must exist before IOP days are billed."]],
  tips:["If a service is not in a signed note, it did not happen as far as the payer is concerned. Bill only what the note shows.","Know the level of care on the authorization before you bill: IOP, PHP and residential are paid and coded differently."],
  remember:"MH + SUD = dual diagnosis. Levels: 1 outpatient, 2.1 IOP, 2.5 PHP, 3+ residential. Notes are the proof: assessment, ASAM, treatment plan, signed progress note, attendance with times.",
  see:[["basics","icd10"],["spec","bh-clinicians"]],
  source:SRC},
 {id:"bh-clinicians",title:"Who gives the care, who can bill, and 42 CFR Part 2",
  keywords:["behavioral health credentials","lcsw","lpcc","lmft","lpp","psychologist","psychiatrist","pmhnp","aprn","lcadc","cadc","alcohol and drug counselor","associate clinician","lcswa","intern billing","supervision billing","peer support specialist","who can bill therapy","rendering provider behavioral","42 cfr part 2","part 2","substance use records privacy","baa","business associate agreement","hipaa behavioral"],
  line:"Psychiatrists and nurse practitioners evaluate and prescribe; psychologists do therapy and testing; licensed clinicians (LCSW, LPCC, LMFT) bill therapy when enrolled and credentialed; associates and interns usually bill under a supervisor; alcohol and drug counselors bill SUD counseling where the payer recognizes them. Never bill under someone who did not render the service. Substance use records carry an extra federal privacy rule, 42 CFR Part 2, stronger than HIPAA.",
  body:[
   "**Prescribers.** A **psychiatrist** (MD or DO) treats mental illness and prescribes; an **APRN or PMHNP** (psychiatric mental health nurse practitioner) and a **PA** can also prescribe. They bill evaluations and medication management, under the payer’s supervision or collaboration rules.",
   "**Therapists.** A **psychologist** (in Kentucky an LPP or licensed psychologist) provides therapy and psychological testing. Independently licensed clinicians, the **LCSW** (licensed clinical social worker), **LPCC** (licensed professional clinical counselor), **LMFT** (licensed marriage and family therapist) and **LPAT** (art therapist), can bill psychotherapy if enrolled and credentialed with the payer. **Associates and interns** (LCSWA, LPCA, LMFTA) are still in training and may need to bill under a supervisor, with supervision documented; each payer decides.",
   "**SUD and peer staff.** A **CADC or LCADC** (certified or licensed alcohol and drug counselor) bills SUD counseling codes where the state and the plan recognize them. **Peer support specialists** need state certification and bill only under the payer’s peer support benefit and supervision rules.",
   "**The billing rule.** Never bill under a provider who did not render the service, and never bill a service by a clinician who is not credentialed with that payer on the date of service. Each license type is enrolled separately with Medicaid (Kentucky gives each its own provider type), so check enrollment for the exact date.",
   "**Privacy.** **PHI** is any health detail that identifies a person, protected by **HIPAA**. Substance use treatment records also fall under **42 CFR Part 2**, a federal rule stronger than HIPAA: they are not shared without the patient’s proper written consent. The updated Part 2 rule’s compliance date was 16 February 2026. A billing company handles a client’s PHI under a **BAA** (business associate agreement), and the client’s Part 2 consent form must cover the billing company."
  ],
  compare:{title:"Who can bill what",head:["Clinician","Typical services","Billing note"],rows:[["Psychiatrist, APRN/PMHNP, PA","Evaluations, medication management (90792, E/M with 90833–90838)","Check enrollment and supervision or collaboration rules"],["Psychologist (LPP)","Psychotherapy, psychological testing (96130–96139)","If enrolled with the payer"],["LCSW, LPCC, LMFT, LPAT","Psychotherapy (90832–90837, 90846, 90847, 90853)","Independently licensed; must be credentialed with the payer"],["Associates and interns (LCSWA, LPCA, LMFTA)","Psychotherapy under supervision","May bill under the supervisor; confirm per payer"],["CADC / LCADC","SUD counseling (H0004, H0005)","Only where the state and the plan recognize them"],["Peer support specialist","Peer support (H0038)","State certification and supervision required"]]},
  terms:[["42 CFR Part 2","The federal rule giving substance use treatment records more privacy protection than HIPAA; sharing needs proper written consent."],["BAA","Business associate agreement: the contract that lets a billing company handle a client’s PHI."],["Credentialed","Approved by the payer to bill under its contract on the date of service."]],
  tips:["Before a claim leaves, match the rendering clinician to their license, their payer enrollment and the date: a therapist credentialed next month is not credentialed today.","Treat every SUD record as Part 2: no sharing on calls or by email beyond what the consent allows."],
  remember:"Prescribers evaluate and prescribe; licensed therapists bill therapy when credentialed; associates under supervision. Never bill under someone who did not render it. SUD records: 42 CFR Part 2, consent first.",
  see:[["basics","hipaa"],["denial","Provider not certified or eligible"]],
  source:SRC}
]},
{id:"bh-b",short:"BH codes",title:"The codes on a behavioral health claim",blurb:"F-code diagnoses and dual-diagnosis order, psychotherapy and SUD service codes, EMDR, place of service and the behavioral modifiers.",lessons:[
 {id:"bh-dx",title:"Diagnosis codes: the F codes and the dual-diagnosis order",
  keywords:["behavioral health diagnosis codes","mental health icd 10","f codes","f10","f11","f12","f14","f32","f33","f41","f43.10","ptsd code","depression code","anxiety code","bipolar code","alcohol use disorder code","opioid use disorder code","dual diagnosis order","which diagnosis first iop","principal diagnosis iop","remission code","in remission","use abuse dependence"],
  line:"Behavioral diagnoses are the F codes of ICD-10-CM: F10–F19 for substance use (alcohol F10, opioids F11, cannabis F12, cocaine F14), F32–F33 for depression, F41 for anxiety, F43.1 for PTSD, F31 for bipolar disorder. The biller never chooses or changes a diagnosis. For a dual-diagnosis IOP claim, the first-listed diagnosis follows the clinician’s documentation and each payer’s policy, not the biller’s judgment.",
  body:[
   "**Three rules of coding.** Billers do not choose diagnoses: copy what the clinician documented. Bill only what the signed note shows. Use the code set for the right year: ICD-10-CM changes every 1 October (the FY2027 set took effect on 1 October 2026), CPT and HCPCS every 1 January.",
   "**The families.** Substance use: F10 alcohol, F11 opioids, F12 cannabis, F13 sedatives, F14 cocaine, F15 other stimulants, F16 hallucinogens, F18 inhalants, F19 other or multiple drugs. Mood: F32 major depression, single episode; F33 recurrent; F31 bipolar. Anxiety F41; PTSD F43.1x; adjustment disorders F43.2x; schizophrenia and other psychotic disorders F20–F29; childhood-onset behavioral disorders F90–F98.",
   "**Specificity.** Code to the highest specificity documented: use, abuse or dependence (F10.1- abuse, F10.2- dependence, for example F10.20 alcohol dependence, uncomplicated), severity, and remission status. Remission or “in recovery” must match the note and the payer’s policy.",
   "**Order on a dual-diagnosis claim.** The first-listed diagnosis is the main reason for the service. For a therapy visit, it is the condition addressed in that session. For a dual-diagnosis IOP it is often the SUD, but payers differ: Passport by Molina’s policy describes co-occurring care as an SUD diagnosis secondary to a primary mental health diagnosis. So use the clinician’s documented principal diagnosis, and get each payer’s rule in writing."
  ],
  compare:{title:"Common behavioral diagnosis families",head:["Category","Codes","Example"],rows:[["Alcohol use","F10.-","F10.20 alcohol dependence, uncomplicated"],["Opioid use","F11.-","F11.20 opioid dependence, uncomplicated"],["Cannabis / cocaine / other stimulants","F12.- / F14.- / F15.-",""],["Other substances","F13.-, F16.-, F18.-, F19.-",""],["Major depression","F32.- single, F33.- recurrent","F33.1 recurrent, moderate"],["Bipolar","F31.-",""],["Anxiety and panic","F41.-",""],["PTSD / adjustment","F43.1- / F43.2-","F43.10 PTSD, unspecified"],["Psychotic disorders","F20–F29","Schizophrenia"],["Childhood-onset","F90–F98","For adolescent programs"]]},
  terms:[["F codes","The mental and behavioral chapter of ICD-10-CM (F01–F99)."],["Principal diagnosis (behavioral)","The main reason for the service, taken from the clinician’s note and the payer’s policy."],["Remission","A documented status in the SUD code (for example F10.21); it must match the note."]],
  tips:["If the note and the claim disagree on the diagnosis, the note wins: send it back for correction, do not edit the code yourself.","Write down each payer’s dual-diagnosis order rule; it is a common reason for medical-necessity denials on IOP."],
  remember:"Diagnosis = the reason, chosen by the clinician. F10–F19 substances, F32/F33 depression, F41 anxiety, F43.1 PTSD. Dual diagnosis order: the clinician’s principal diagnosis and the payer’s rule.",
  see:[["basics","icd10"]],
  source:SRC},
 {id:"bh-cpt",title:"Service codes: psychotherapy, SUD H codes, EMDR, POS and modifiers",
  keywords:["psychotherapy codes","90832","90834","90837","90833","90836","90838","90791","90792","90846","90847","90853","90839","90840","h0001","h0004","h0005","h0038","h2011","h2027","t1016","t2023","h0006","h0020","96130","psychological testing","emdr code","emdr billing","how to bill emdr","90884","behavioral health pos","pos 10","pos 02","modifier 95","modifier 93","telehealth modifier behavioral","ho modifier","hn modifier","hf modifier","hg modifier","ha modifier","hb modifier","gt modifier behavioral"],
  line:"Therapy is billed with time-based CPT codes: 90832 (16–37 minutes), 90834 (38–52) and 90837 (53 or more), with 90791 or 90792 for the evaluation, 90846 and 90847 for family therapy and 90853 for group. SUD services use HCPCS H codes (H0001 assessment, H0004 counseling per 15 minutes, H0005 group, H0038 peer support). EMDR has no code of its own: it is billed with the psychotherapy code for the session length. POS and the payer’s telehealth modifier must agree.",
  body:[
   "**Psychotherapy by time.** Code by the actual face-to-face time documented: **90832** 16–37 minutes, **90834** 38–52 minutes, **90837** 53 minutes or more. A prescriber who also does an E/M visit adds **90833, 90836 or 90838** to the E/M code. **90791** is the psychiatric diagnostic evaluation without medical services, **90792** with medical services (prescribers only), usually once per episode. **90846** is family therapy without the patient, **90847** with the patient, **90853** group therapy (billed per patient, with each patient’s own note). Crisis: **90839** (first 60 minutes) and **90840** (each added 30), or **H2011**. Psychological testing: **96130–96139**, usually with prior authorization.",
   "**HCPCS H, S and T codes.** State Medicaid programs use letter codes for behavioral services: **H0001** alcohol and drug assessment (not the same as 90791); **H0004** SUD individual counseling per 15 minutes; **H0005** SUD group counseling; **H0015** SUD or co-occurring IOP, per diem; **S9480** mental health IOP, per diem; **H0038** peer support per 15 minutes; **H2027** psychoeducation; **T1016, H0006 or T2023** case management (T2023 is targeted case management on some plans). **H0020** is methadone administration or service, not general medication management: do not use it for MAT coordination without the payer’s say-so. Coverage of each varies by plan.",
   "**EMDR.** There is no CPT code for EMDR. Bill it with the psychotherapy code for the session length (90832, 90834 or 90837). Some payers have EMDR policies or ask for extra documentation. Do not use 90884 or any code suggested by online forums or AI tools without the payer’s confirmation. On an IOP day, individual therapy, EMDR included, is part of the per diem and is not billed separately.",
   "**Place of service.** **11** in person at the clinic; **10** telehealth with the patient at home; **02** telehealth with the patient elsewhere. A POS and modifier mismatch is one of the most common telehealth denials.",
   "**Modifiers.** Telehealth: **95** audio-video, **93** audio-only (Passport by Molina accepts only these, with POS 02 or 10); **GT**, **FQ** and **FR** have specific payer meanings and are used only when a payer says so. Clinician level and program modifiers, used only when the payer requires them: **HO** master’s level, **HN** bachelor’s level, **HF** substance abuse program, **HG** opioid treatment program, **HA** child or adolescent program, **HB** adult program (the age that counts as adult varies by payer)."
  ],
  compare:[{title:"Psychotherapy and evaluation codes",head:["Code","Service","Rule"],rows:[["90791 / 90792","Diagnostic evaluation, without / with medical services","Usually once per episode; 90792 by a prescriber"],["90832","Psychotherapy, 16–37 minutes","Time documented"],["90834","Psychotherapy, 38–52 minutes","Time documented"],["90837","Psychotherapy, 53 minutes or more","Time documented"],["90833 / 90836 / 90838","Psychotherapy added to an E/M visit","Prescriber only, with the E/M code"],["90846 / 90847","Family psychotherapy without / with the patient","Document who attended"],["90853","Group psychotherapy","Per patient, each with a note"],["90839 / 90840","Crisis psychotherapy, first 60 / each added 30 minutes","Only if crisis services are offered"],["96130–96139","Psychological and neuropsychological testing","Usually needs authorization"]]},
   {title:"HCPCS codes for behavioral and SUD services",head:["Code","Service","Note"],rows:[["H0001","Alcohol and drug assessment","Not the same as 90791"],["H0004","SUD individual counseling, per 15 minutes","Coverage by plan"],["H0005","SUD group counseling","Coverage by plan"],["H0015","SUD / co-occurring intensive outpatient, per diem","See the IOP topic"],["S9480","Mental health intensive outpatient, per diem","Commercial and Medicaid; not Medicare"],["H0038","Peer support, per 15 minutes","Certification and supervision"],["H2011 / H2027","Crisis intervention / psychoeducation",""],["T1016, H0006, T2023","Case management","Code per plan"],["H0020","Methadone administration or service","Not general MAT coordination"],["H0035","Partial hospitalization","A different level; never for IOP"]]}],
  terms:[["Time-based code","A code chosen by documented minutes, such as 90832, 90834 and 90837."],["EMDR billing","No own code: bill the psychotherapy code that matches the session length."],["POS 10 / 02","Telehealth with the patient at home / somewhere other than home."]],
  tips:["Read the start and stop times in the note before choosing a psychotherapy code: 52 minutes is 90834, 53 is 90837.","Run a POS and modifier edit on every telehealth claim before it goes out."],
  remember:"Therapy by time: 90832 / 90834 / 90837. Evaluation 90791 / 90792. Group 90853, family 90846 / 90847. SUD: H0001, H0004, H0005, H0038. IOP per diem: H0015, S9480. EMDR = the time code. POS 11 / 10 / 02 with the payer’s modifier.",
  see:[["basics","cpt-hcpcs"],["basics","modifiers"]],
  source:SRC}
]},
{id:"bh-c",short:"IOP billing",title:"Intensive outpatient programs (IOP)",blurb:"Per diem billing, revenue codes and HCPCS pairing, minimum hours, same-day exclusions, the UB-04 field by field, and Medicare’s IOP rules.",lessons:[
 {id:"bh-iop",title:"IOP billing: per diem, revenue codes, minimum hours and what cannot be billed the same day",
  keywords:["iop billing","intensive outpatient billing","per diem","per diem billing","what is per diem","h0015","s9480","h0015 vs s9480","revenue code 0905","revenue code 0906","0905","0906","0907","0912","0913","iop revenue code","iop units","iop minimum hours","iop documentation","iop same day","bill therapy on iop day","iop unbundled","iop duplicate denial","iop attendance","iop weekly claim"],
  line:"An IOP is paid per diem: one payment, one unit, for each qualifying day the patient attends, covering all the therapy that day. H0015 is the SUD or co-occurring IOP code, S9480 the mental health IOP code; on a UB-04 they sit under revenue code 0905 (psychiatric IOP) or 0906 (chemical dependency IOP), and the pairing varies by payer. Individual, group, family and crisis services on an IOP day are part of the per diem and deny if billed separately.",
  body:[
   "**Per diem.** Latin for “for each day”. Instead of billing each session, the program bills one daily unit that covers everything delivered that day: group therapy, individual counseling, psychoeducation, relapse prevention, family work. Payers usually expect at least about 3 hours of programming for a qualifying day.",
   "**The codes.** **H0015** (alcohol and/or drug services, intensive outpatient) for SUD or co-occurring programs; **S9480** (intensive outpatient psychiatric services, per diem) for mental health programs. S codes are used by commercial plans and Medicaid; Medicare does not pay them. On a facility claim the revenue code is **0905** (intensive outpatient, psychiatric) or **0906** (intensive outpatient, chemical dependency). The common pairing is S9480 with 0905 and H0015 with 0906, but payers differ: Passport by Molina pays both under 0905. Do not hard-code the pairing; follow each payer’s policy.",
   "**Not IOP.** Revenue code **0907** is a community behavioral health program (day treatment), not psychiatric rehabilitation as one training sheet says. **0912 and 0913** and HCPCS **H0035** are partial hospitalization, a different level of care. **0900** is general behavioral health and is not used for IOP.",
   "**Minimum intensity.** Payers set a floor for a billable IOP week. Kentucky Medicaid, for example, requires adults to attend at least 3 hours a day, on at least 3 days, for at least 9 hours a week, and adolescents at least 6 hours over at least 2 days. A week below the minimum may deny. Medicare requires a physician to certify the need for at least 9 hours a week.",
   "**What cannot be billed on an IOP day.** The per diem includes individual psychotherapy (90832–90838), group (90853), family therapy (90846, 90847, 90849), crisis (90839, 90840, H2011) and psychoeducation (H2027), so they deny as duplicate or unbundled on the same date, as does any other per diem code, residential included. Exceptions are narrow and payer-specific: Passport allows targeted case management (T2023) and an evaluation (90791, 90792) only outside IOP hours, documented as separate and necessary. Some payers allow unbundled session billing instead of a per diem; follow the payer.",
   "**Documentation for every billed day.** An individualized treatment plan; a signed progress note showing active participation; an attendance record with start and stop times proving the hours; and the ASAM-supported medical necessity for the authorized level. No chart, no bill: claims paid without it are recouped after audit."
  ],
  compare:[{title:"IOP codes at a glance",head:["Code","What it is","Use"],rows:[["H0015","SUD / co-occurring IOP, per diem","Usually revenue code 0906 (some payers 0905)"],["S9480","Mental health IOP, per diem","Usually revenue code 0905; not paid by Medicare"],["0905","Revenue code: intensive outpatient, psychiatric","IOP, mental health"],["0906","Revenue code: intensive outpatient, chemical dependency","IOP, SUD"],["0907","Revenue code: community behavioral health program (day treatment)","Not IOP"],["0912 / 0913, H0035","Partial hospitalization","A different level of care"],["0900","Behavioral health, general","Not IOP; Medicare uses it for non-IOP mental health visits at RHCs and FQHCs"]]},
   {title:"On an IOP day",head:["Service","Billed separately?"],rows:[["Individual psychotherapy 90832–90838, EMDR included","No: part of the per diem"],["Group 90853, family 90846 / 90847 / 90849","No"],["Crisis 90839 / 90840 / H2011, psychoeducation H2027","No"],["Another per diem (residential, PHP)","No: duplicative"],["Evaluation 90791 / 90792","Only outside IOP hours, separate and documented (Passport)"],["Targeted case management T2023","Only outside IOP hours (Passport)"]]}],
  terms:[["Per diem","One payment and one unit for each qualifying program day."],["Qualifying day","A day that meets the payer’s minimum hours, with a signed note and attendance."],["Unbundled","A service billed separately that the payer counts as part of another payment, here the per diem."]],
  tips:["Before billing a day, check three things in the record: the signed note, the attendance times that prove the hours, and the authorization covering the date and code.","When an IOP claim denies for duplicate service, look for a therapy or crisis code billed on the same date by another clinician."],
  remember:"IOP = per diem: one unit per qualifying day. H0015 SUD, S9480 MH; revenue 0905 / 0906, pairing per payer. Therapy, group, family, crisis, psychoeducation on an IOP day: not billed. No note and attendance, no bill.",
  see:[["spec","bh-ub04"],["spec","bh-ky-iop"],["denial","Procedure code not paid separately"]],
  source:SRC},
 {id:"bh-ub04",title:"The UB-04 for IOP, field by field, and the pre-submission checklist",
  keywords:["ub-04 iop","ub04 iop","ub 04 iop","iop claim form","cms 1450 iop","837i iop","iop on cms-1500","ub-04 form locators","form locator","fl 4 type of bill","type of bill iop","fl 42","fl 44","fl 63","box 63","treatment authorization code","statement covers period","fl 6","fl 46 units","iop checklist","pre-submission checklist","institutional billing","facility billing behavioral"],
  line:"Facility-style IOP claims go on the UB-04 (CMS-1450, electronically the 837I) with a revenue code, the IOP HCPCS code, a line per date of service and one unit per qualifying day; the prior authorization number goes in form locator 63. Some payers want IOP on the CMS-1500 (837P) instead: which form depends on the provider’s enrollment and the payer’s contract.",
  body:[
   "**Institutional versus professional.** The **UB-04** (CMS-1450, 837I) is for services billed by a facility or program, with revenue codes; the **CMS-1500** (837P) is for services by an individual clinician or practice. Hospitals, community mental health centers, RHCs and FQHCs bill IOP on the UB-04. Some state Medicaid programs and plans want IOP on the CMS-1500: Kentucky Medicaid’s behavioral health organization page says CMS-1500, while the MCOs’ IOP policies list revenue codes. Confirm the form for each payer before the first claim.",
   "**The fields that matter for IOP.** Type of bill (FL 4) has three digits: the facility type, the classification and the frequency (1 original, 7 replacement, 8 void); hospital outpatient is 13X, a critical access hospital 85X, an RHC 71X, an FQHC 77X. The statement covers period (FL 6) is the billing week. Each date gets its own line (FL 45) with the revenue code (FL 42), the HCPCS code and modifiers (FL 44), one unit per day (FL 46) and the charge (FL 47). The authorization number goes in **FL 63**; the diagnoses in FL 67 (principal) and 67A–Q; the attending clinician in FL 76.",
   "**Corrections to the training sheet.** HCPCS for IOP are H and S codes (H0015, S9480), not G codes. Use current NUBC definitions and the payer’s own UB-04 instructions, which override any guide.",
   "**Before you submit.** Run the checklist: patient name, birth date and member ID match eligibility; the right payer and payer ID for every day; an active authorization that covers the dates, code, revenue code and units; the HCPCS and revenue code pairing the payer wants; the week and the statement dates agree; the minimum days and hours are met; a signed note and attendance for each day; no therapy, group, family, crisis or other per diem code on an IOP day; a documented first-listed diagnosis; the required modifiers and telehealth POS; billing NPI, taxonomy and tax ID matching the enrollment; the right type of bill and frequency; no duplicate lines."
  ],
  compare:{title:"UB-04 form locators for an IOP claim",head:["FL","Field","What to enter"],rows:[["1","Billing provider","Name, address, phone"],["3a / 3b","Patient control / medical record number","Billing account number / chart number"],["4","Type of bill","Facility type, classification, frequency (1 original, 7 replacement, 8 void), per payer"],["5","Federal tax ID","The client’s EIN"],["6","Statement covers period","First and last date of the billing week"],["8–11","Patient name, address, birth date, sex","Exactly as on eligibility"],["18–28","Condition codes","Only when the payer requires them (Medicare IOP: 92)"],["42 / 43","Revenue code / description","0905 or 0906 as the payer requires"],["44","HCPCS / modifiers","H0015 or S9480, plus any required modifier (HA, HB)"],["45","Service date","One line per date of service"],["46","Units","One per qualifying day"],["47","Total charges","Per line; total on the last line"],["50 / 51","Payer / plan ID","The correct payer for the dates"],["56","Billing provider NPI","The organization’s Type 2 NPI"],["58 / 60","Insured name / member ID","Exactly as on eligibility"],["63","Treatment authorization code","The prior authorization number"],["67, 67A–Q","Principal and other diagnoses","Principal per the clinician and the payer’s rule, then co-occurring"],["76","Attending provider","The responsible clinician’s NPI"],["80","Remarks","Short notes only when needed, such as a corrected-claim reason"]]},
  terms:[["UB-04 (CMS-1450, 837I)","The institutional claim form, with revenue codes and form locators."],["Form locator (FL)","A numbered field on the UB-04."],["Type of bill","The three-digit FL 4 code: facility type, classification and claim frequency."],["FL 63","Treatment authorization code: where the prior authorization number goes."]],
  tips:["The authorization number in FL 63 must match the one in the authorization log for those dates, codes and units.","For a corrected IOP claim, change the frequency digit of the type of bill (7 replacement, 8 void) and give the reason in FL 80."],
  remember:"IOP on the UB-04: revenue code FL 42, HCPCS FL 44, a line per date FL 45, one unit FL 46, authorization FL 63, diagnoses FL 67. Form per payer: UB-04 or CMS-1500. Checklist before every claim.",
  see:[["basics","claim-forms"],["spec","bh-iop"]],
  source:SRC},
 {id:"bh-medicare-iop",title:"Medicare IOP (2024 onward): hospitals, RHCs and FQHCs",
  keywords:["medicare iop","medicare intensive outpatient","cr 13264","mm13264","condition code 92","revenue code 0519","rhc iop","fqhc iop","cg modifier","list a list b","iop wrap around","medicare advantage wrap around","iop plan of care","iop certification","9 hours per week","iop recertification","0900 vs 0905","iop same day medical visit","259.13"],
  line:"Since 1 January 2024 Medicare covers intensive outpatient services in hospital outpatient departments, community mental health centers, rural health clinics (RHCs) and federally qualified health centers (FQHCs). RHC and FQHC IOP claims use revenue code 0905 with condition code 92 and at least one List A service code, are paid per diem outside the clinic’s usual all-inclusive or PPS rate, and need a physician-certified plan of care showing the need for at least 9 hours a week.",
  body:[
   "**What changed (CR 13264, MLN MM13264).** From 1 January 2024 Medicare pays IOP for RHCs, FQHCs and grandfathered tribal FQHCs, outside the RHC all-inclusive rate (AIR) and the FQHC prospective payment system (PPS), at the same per diem as hospital-based IOP. The training sheet quotes the 2024 figure for three services a day, $259.13: RHCs were paid that amount, FQHCs the lesser of their charges or that amount, and tribal FQHCs the lesser of charges or the IHS outpatient per-visit rate. Medicare updates the IOP rate every year, so use the current fee schedule, not the 2024 number.",
   "**How the claim is coded.** Revenue code **0905** and condition code **92** (which marks the claim as IOP). Revenue code 0900 is for non-IOP mental health visits and is not used for IOP. The claim must carry at least one **List A** (primary) service code; **List B** services are bundled. RHCs report modifier **CG** on the payment line so coinsurance is calculated; FQHCs report all charges on the primary service line.",
   "**Same-day visits.** IOP plus a mental health visit on the same day: one payment, at the IOP rate; the mental health visit is included. IOP plus a medical visit: both are paid (the IOP rate and the PPS or AIR). A mental health visit with no IOP: revenue code 0900. IOP only: 0905 with condition code 92.",
   "**Medicare Advantage wrap-around (FQHC).** When a Medicare Advantage plan pays an FQHC less than the PPS rate, Medicare pays the difference. To get it, the claim reports condition code 92, revenue code 0519, a List A code and any List B codes.",
   "**Covered services.** Medically necessary, therapeutic services ordered in a structured plan: individual and group psychotherapy; occupational therapy; services of social workers, psychiatric nurses and other licensed staff; drugs that are not self-administered; family counseling focused on the patient’s treatment; activity therapy that is therapeutic, not recreational; patient education linked to care; and diagnostic services for mental health or substance use.",
   "**Plan of care and certification.** A written treatment plan, signed and certified by a physician, with the diagnosis, the type, frequency and duration of each service, the goals, and the physician’s certification that the patient needs at least 9 hours of IOP services a week. Recertification is due no later than the 60th day and then at least every 60 days. A missing or incomplete plan of care means denials."
  ],
  compare:{title:"Medicare IOP coding at RHCs and FQHCs",head:["Situation","Revenue code","Condition code","Note"],rows:[["IOP only","0905","92","At least one List A code; List B bundled"],["IOP + mental health visit, same day","0905","92","One payment at the IOP rate"],["IOP + medical visit, same day","0905 and the medical line","92","Both paid: IOP rate and PPS or AIR"],["Mental health visit, no IOP","0900","—","Regular clinic payment"],["FQHC Medicare Advantage wrap-around","0519","92","With a List A code and any List B codes"],["RHC payment line","0905","92","Modifier CG on the payment line"]]},
  terms:[["Condition code 92","The UB-04 condition code that identifies an IOP claim to Medicare."],["List A / List B","Medicare’s IOP service lists: a claim needs at least one List A (primary) code; List B codes are bundled."],["AIR / PPS","The RHC all-inclusive rate and the FQHC prospective payment system; Medicare IOP is paid outside them."],["Wrap-around payment","Medicare paying an FQHC the difference when a Medicare Advantage plan pays less than PPS."]],
  tips:["Separate Medicare IOP claims during AR review: they are paid on their own rate, not the clinic’s AIR or PPS.","Check the plan of care date before every Medicare IOP week: a certification past 60 days without recertification will deny."],
  remember:"Medicare IOP at RHCs and FQHCs: 0905 + condition code 92 + a List A code; not 0900. RHC: CG. FQHC MA wrap-around: 0519 + CC 92. Plan of care certified for at least 9 hours a week, recertified every 60 days. Rates change yearly.",
  see:[["basics","medicare"],["spec","bh-ub04"]],
  source:SRC}
]},
{id:"bh-d",short:"BH payers and AR",title:"Authorization, telehealth, denials and AR",blurb:"Prior authorization as the biggest revenue risk, telehealth rules, the IOP denials and how to clean up behavioral health AR.",lessons:[
 {id:"bh-auth",title:"Prior authorization for IOP and behavioral services",
  keywords:["iop prior authorization","iop authorization","behavioral health prior authorization","bh pa","authorization log","auth log","continued stay","continued stay request","concurrent review","retro authorization behavioral","units exceeded","authorization expired iop","asam assessment authorization","house bill 695","hb 695"],
  line:"Authorization is the highest revenue risk on a behavioral health account. Request it with the assessment, the ASAM level-of-care justification and the treatment plan; log the number, approved codes, units or days, dates, provider and level of care; track used against approved days every week; and request a continued stay before it expires. Never bill a date, code, unit, provider or level of care outside the authorization.",
  flow:{steps:["Check the payer’s current authorization list for IOP, assessments, testing, EMDR and case management (lists change; check the payer’s site, not a guide)","Collect the clinical packet: intake or assessment, diagnoses, **ASAM assessment** and level-of-care justification, **treatment plan**, requested frequency and duration","Submit through the right portal (fee-for-service or the specific plan; some plans route behavioral health through a vendor such as Optum)","**Log** the authorization number, approved codes and revenue code, units or days, dates, rendering and requesting provider, level of care","Track **used versus approved** days every week","Request a **continued stay** before the authorization expires, usually several days to a week ahead","Appeal denials and partial approvals with clinical support; ask each plan whether retro authorization is allowed, and for how long"],to:"Bill only inside the authorization"},
  body:[
   "**Why it matters.** IOP is expensive, so payers approve it for a set number of days at a set level, and stop paying the day after. An authorization is not a guarantee of payment either: the claim must still match it exactly and meet the documentation rules.",
   "**Kentucky example.** Kentucky’s House Bill 695 (2025) made the state reinstate the behavioral health authorization rules of 1 January 2020, effective 25 June 2025. The state’s grid (revised August 2025) shows authorization required for IOP (S9480, H0015, revenue codes 0905 and 0906) at all five Medicaid managed care plans.",
   "**The log.** Patient and payer (member ID, authorization number); what is approved (codes and revenue code, diagnosis, units, days or visits, start and end dates, level of care, frequency limit); providers (rendering and requesting); status (submission and decision dates, expiration, continuation request date, denial and appeal status). The log is what the biller checks before every claim."
  ],
  terms:[["Continued-stay review","A request, with clinical updates, to extend an authorization at the same level of care."],["Retro authorization","Approval requested after the service; allowed only by some payers, for limited periods."],["Units exceeded","More days or units billed than the authorization approved."]],
  tips:["Set a reminder 7 days before every IOP authorization ends, and check the used days every Monday.","When the level of care changes (IOP to outpatient), the old authorization does not carry over: a new one is needed."],
  remember:"Authorization = biggest risk. Packet: assessment, ASAM, treatment plan. Log everything. Track weekly. Continued stay before expiry. Never bill outside the authorization.",
  see:[["basics","managed-care"],["denial","Authorization absent or missing"]],
  source:SRC},
 {id:"bh-telehealth",title:"Telehealth for behavioral health and IOP",
  keywords:["behavioral telehealth","telehealth therapy billing","telehealth iop","video therapy billing","audio only therapy","audio-only","modifier 95","modifier 93","pos 10","pos 02","telehealth consent","telehealth note","telehealth denial behavioral"],
  line:"Before billing a behavioral telehealth visit, confirm the plan covers that service by telehealth (group therapy and IOP days included), whether audio-only is payable, and the payer’s POS and modifier combination; the note must record the platform, start and stop times, participants, both locations and the consent. IOP hours delivered by telehealth count toward the minimum only if the plan allows it.",
  body:[
   "**The checks.** The plan covers the service by telehealth; audio-video versus audio-only; the right POS (02 or 10) with the payer’s modifier (for example 95 for audio-video and 93 for audio-only on Passport by Molina; other plans have their own rules, and Optum requires POS 02 or 10 on every behavioral telehealth claim); the patient’s and provider’s locations documented; consent on file.",
   "**The note.** Platform, start and stop time, who took part, and the interventions. A telehealth note without times cannot support a time-based code or an IOP day.",
   "**IOP by telehealth.** Some plans allow IOP face to face or by telehealth; others do not count telehealth hours toward the daily or weekly minimum. Confirm per plan before scheduling telehealth IOP days."
  ],
  compare:{title:"Telehealth at a glance",head:["Item","What to check"],rows:[["POS","10 patient at home, 02 patient elsewhere"],["Modifier","Per payer: 95 audio-video, 93 audio-only; GT, FQ, FR only if the payer says so"],["Coverage","The service, group therapy and IOP days by telehealth"],["Note","Platform, start and stop time, participants, locations, consent"]]},
  terms:[["Audio-only","Telehealth by phone with no video; payable only where the plan allows it, often with modifier 93."]],
  tips:["The most common behavioral telehealth denial is a POS and modifier pair the payer does not accept: check it on every claim."],
  remember:"Telehealth: covered service? audio-only allowed? POS 02 / 10 with the payer’s modifier; note with times, participants, locations, consent. IOP hours count only if the plan allows telehealth IOP.",
  see:[["spec","bh-cpt"]],
  source:SRC},
 {id:"bh-denials",title:"Behavioral health denials and AR cleanup",
  keywords:["iop denials","behavioral health denials","bh denials","iop denied","medical necessity iop","no iop benefit","iop recoupment","denial log","ar cleanup","ar clean up","aged trial balance","behavioral ar","segregate by denial reason","documentation audit","iop audit","turnaround standards","denial prevention iop"],
  line:"Most behavioral and IOP denials are one of six: authorization (missing, expired, units exceeded), eligibility (inactive, wrong plan), medical necessity (notes, hours or level of care not supported), coverage (no IOP benefit), duplicate or unbundled (a session code on an IOP day) and format (dates, week span, POS or modifier, code pairing). Work denials within 24 to 48 hours, log every one, and fix the cause so it does not repeat.",
  body:[
   "**First check for each.** Authorization: the log against the claim’s dates, codes and units; retro authorization if allowed, or appeal. Eligibility: re-verify, correct, rebill the right payer. Medical necessity: the notes, attendance times and ASAM support; appeal with clinical records and the payer’s policy. Coverage: the plan’s benefits; no IOP benefit means another payer or the client’s policy. Duplicate or unbundled: look for a therapy, crisis or other per diem code on the same date. Format: statement dates, the week span, the revenue code pairing, POS and modifiers; correct and resubmit.",
   "**AR cleanup.** Pull the aged trial balance; segregate by denial reason (authorization, eligibility, coding, medical necessity, duplicate); prioritize high-dollar and high-volume payers; check the payer portal before calling; batch the corrected claims; work claims over 30, 60 and 90 days first; separate IOP claims (and Medicare IOP, paid on its own rate) in the analysis.",
   "**Prevention.** Stay ahead of expiring authorizations; match every claim line to an attended session and a documented diagnosis; use the pre-submission checklist; run weekly or monthly self-audits (random charts, time tracking, HCPCS and revenue code match, provider credentials).",
   "**Recoupment.** Claims paid outside the payer’s IOP rules can be taken back after review (Aetna Better Health of Kentucky cites state law for it). A clean per diem today is only safe if the notes and attendance prove it.",
   "**Turnaround standards (a good working target).** Eligibility before the first service, monthly for IOP patients and before each billing week; charges within 1 business day of the signed note; claims within 2 business days (IOP: of the last signed note of the week); clearinghouse rejections the same day; ERA posting within 1 business day; denials within 2 business days; appeals at least 10 days before the deadline; a weekly report every Monday."
  ],
  compare:{title:"The behavioral and IOP denials",head:["Category","Typical cause","Action"],rows:[["Authorization","None, expired, units exceeded, wrong level or code","Check the log; retro authorization if allowed; appeal or correct"],["Eligibility","Inactive coverage, wrong plan, ID mismatch","Re-verify, correct, rebill the right payer"],["Medical necessity","Notes, hours or ASAM support missing","Appeal with clinical records and the payer’s policy"],["Coverage","The plan has no IOP benefit","Check other coverage and the client’s policy"],["Duplicate / unbundled","A session or per diem code on an IOP day","Remove the line or appeal a documented exception"],["Format","Dates, week span, revenue code pairing, POS or modifier","Correct and resubmit"]]},
  terms:[["Aged trial balance","The AR report of unpaid claims grouped by age (0–30, 31–60, 61–90, over 90 days)."],["Denial log","Patient, payer, date of service, claim number, code, amount, denial code, category, root cause, owner, action, outcome, amount recovered, preventable or not."]],
  tips:["Log the root cause, not only the denial code: three IOP denials for the same missing attendance times are one fix upstream.","A medical-necessity appeal for IOP needs the ASAM assessment, the treatment plan and the attendance for the denied days."],
  remember:"Six denials: authorization, eligibility, medical necessity, coverage, duplicate on an IOP day, format. Work in 24–48 hours, log every one, fix the cause. AR cleanup: aged balance, by reason, big payers first, portal before phone.",
  see:[["basics","appeals-grievances"],["denial","Medically not necessary"]],
  source:SRC}
]},
{id:"bh-e",short:"Kentucky IOP",title:"Kentucky Medicaid IOP: a state example",blurb:"Kentucky Medicaid’s plans, deadlines and enrollment, and the IOP rules of the Kentucky plans: the weekly claim, minimum hours and what is still to confirm.",lessons:[
 {id:"bh-ky",title:"Kentucky Medicaid: FFS and the five MCOs, enrollment and deadlines",
  keywords:["kentucky medicaid","ky medicaid","kentucky mco","kentucky mcos","aetna better health of kentucky","humana healthy horizons","passport by molina","passport health plan","wellcare of kentucky","unitedhealthcare community plan kentucky","gainwell","kentucky ffs","anthem kentucky medicaid","kentucky timely filing","kentucky appeal deadline","bhso","provider type 03","kentucky provider type","128ky","payer id 128ky"],
  line:"Most Kentucky Medicaid members are in one of five managed care plans (Aetna Better Health of Kentucky, Humana Healthy Horizons, Passport by Molina, UnitedHealthcare Community Plan, WellCare of Kentucky); the rest are fee-for-service, processed by Gainwell Technologies. Anthem left Kentucky Medicaid on 1 January 2025. Each plan has its own IDs, portal, authorization rules, edits and deadlines: check FFS versus MCO for every date of service and never apply one plan’s rule to another.",
  body:[
   "**Why this module.** Kentucky is a worked example of how a state Medicaid program and its plans set IOP rules. A typical behavioral health provider there runs an intensive outpatient program, outpatient mental health with dual-diagnosis care (trauma-informed therapy, EMDR, CBT, DBT, motivational interviewing, MAT coordination) and telehealth, and sometimes supportive housing, which is non-clinical and not billable unless a covered benefit is documented. Such an account is an IOP and SUD account, not a simple therapy practice: authorization, the per diem rules and code selection drive most of the revenue risk. Other states follow the same pattern with their own rules.",
   "**Plans.** Five MCOs, and fee-for-service through Gainwell. Anthem is no longer a Kentucky Medicaid plan: a patient showing an Anthem card needs a fresh eligibility check. Members can change plans, so re-verify IOP patients at least monthly and before each billing week. UnitedHealthcare Community Plan routes behavioral health authorizations through Optum. Aetna Better Health of Kentucky’s electronic payer ID is 128KY; get every other payer ID from the plan and the clearinghouse.",
   "**Enrollment decides the setup.** Kentucky enrolls behavioral health organizations as Behavioral Health Service Organizations (BHSO, provider type 03, licensed by tier) and also enrolls behavioral health provider groups and multi-specialty groups; each independent license is enrolled under its own provider type (for example LCSW 82, LPCC 81, LMFT 83, LPP 84, LCADC 67). The provider must be active with Medicaid and with each member’s plan. Which type the client holds decides the claim form, the rates and what can be billed.",
   "**Deadlines.** Fee-for-service: 12 months from the date of service (or 6 months from the Medicare payment date, or 12 months from the last Kentucky Medicaid denial, if later). Aetna Better Health: 365 days from the date of service; corrected claims within 24 months of the remittance; appeals 60 days from the notification. Humana Healthy Horizons: 365 days; appeals 60 days from the notice. Passport: 365 days; denied claims 365 days from the denial (60 days after a recoupment request); Passport has accepted only fax confirmation or a signed postal receipt as proof of timely filing. UnitedHealthcare and WellCare: confirm. Good practice: escalate any claim not sent within 30 days of the date of service; for IOP the clock starts at the end of the billing week."
  ],
  compare:{title:"Kentucky Medicaid deadlines (the contract controls)",head:["Payer","Initial claim","Corrected / resubmission","Appeal"],rows:[["Kentucky FFS (Gainwell)","12 months from DOS (or 6 months from the Medicare pay date, or 12 months from the last KY Medicaid denial, if later)","Same rule","To Gainwell with the reason and a hard-copy claim"],["Aetna Better Health of Kentucky","365 days from DOS","Within 24 months of the remittance","60 days from the notification"],["Humana Healthy Horizons","365 days from DOS","Confirm","60 days from the notice or denial"],["Passport by Molina","365 days from DOS","Denied claims 365 days from the denial; 60 days after a recoupment request","Confirm"],["UnitedHealthcare Community Plan","Confirm","Confirm","Confirm"],["WellCare of Kentucky","Confirm","Confirm","Payment appeals within 24 months of the EOP (confirm)"]]},
  terms:[["MCO","Managed care organization: a health plan that runs Medicaid benefits for its members."],["FFS","Fee-for-service Medicaid, paid by the state’s fiscal agent (Gainwell) rather than a plan."],["BHSO","Behavioral Health Service Organization, Kentucky Medicaid provider type 03."]],
  tips:["Read the plan name on the eligibility response for every date of service: a member who switched plans mid-week splits the IOP week across payers.","Items marked confirm are not settled: ask the lead, never guess them."],
  remember:"Kentucky: five MCOs (Aetna, Humana, Passport, UHC Community, WellCare) plus FFS through Gainwell; no Anthem since 2025. Each plan, its own rules. Re-verify IOP patients monthly and each billing week.",
  see:[["basics","medicaid"],["spec","bh-ky-iop"]],
  source:SRC_KY},
 {id:"bh-ky-iop",title:"Kentucky IOP rules: one claim per week, minimum hours and the open questions",
  keywords:["kentucky iop","ky iop","one claim per week","weekly iop claim","rolling seven day week","rolling 7 day","iop week","iop billing week","aetna iop policy","passport iop policy","kentucky iop minimum hours","3 hours 3 days 9 hours","adolescent iop 6 hours","iop same day kentucky","h0020 h0047","t2023 iop","kentucky iop telehealth","iop open questions","iop confirm items"],
  line:"Aetna Better Health of Kentucky and Passport by Molina require one IOP claim per rolling seven-day week, starting on the first date of service on the claim, with the statement dates matching that week; adults need at least 3 hours a day, 3 days and 9 hours a week, adolescents at least 6 hours over 2 days. Hold the days until the week is complete and every note is signed, then bill once. Humana, UnitedHealthcare and WellCare may differ: confirm in writing.",
  flow:{steps:["Start the week on the **first IOP date of service**: the week is any seven consecutive days, not Sunday to Saturday","Hold each day until its **note is signed** and the **attendance** shows the hours","At the end of the seven days, check the **minimum**: adults 3 days, 3 hours each, 9 hours in total; adolescents 2 days and 6 hours","Check the **authorization** covers every day, the code, the revenue code and the units","Check the member was with the **same plan** on every day","Build **one claim** for the week: statement from and through dates matching the seven days, one line per day, one unit per day","No therapy, group, family, crisis or psychoeducation codes on any IOP day","Submit within 2 business days of the last signed note of the week"],to:"Post the ERA; work any denial within 2 business days"},
  body:[
   "**The policies behind it.** Kentucky’s Department for Medicaid Services sets the IOP standards and the plans apply them in their own policies: Aetna Better Health of Kentucky (effective 1 May 2026) and Passport by Molina (effective 19 April 2026). IOP must be a structured, multi-modal, multi-disciplinary program: individual, group and family therapy (unless contraindicated), crisis intervention and psychoeducation, as each treatment plan requires. Passport allows IOP face to face or by telehealth.",
   "**Codes on these plans.** H0015 is the SUD and co-occurring IOP code and S9480 the mental health code; Passport describes H0015 as covering co-occurring disorders. Aetna lists revenue codes 0905 and 0906; Passport pays H0015 or S9480 under 0905. So the pairing is set per plan, and one unit per qualifying day is the usual unit (confirm).",
   "**One claim per week.** All IOP days in a rolling seven-day period go on the same claim. A claim spanning more than seven days, or with fewer than the minimum days, may be denied. Do not split a week across claims and do not bill each day as it happens.",
   "**Narrow exceptions.** Passport allows targeted case management (T2023) on an IOP day only for separate care coordination outside IOP hours, and an evaluation (90791, 90792) only outside IOP hours, not duplicative and documented as necessary. Passport also notes that H0020 and H0047 are weekly bundled codes that H0015 may not be billed outside of. Both plans say their code lists are not complete, so other codes may be blocked too. WellCare’s July 2026 notice, citing the state, treats IOP, psychotherapy and other outpatient behavioral codes billed on the same day as a residential SUD per diem as duplicative.",
   "**What to confirm in writing before billing a Kentucky IOP account.** Enrollment type, license tier and plan contracts; which plans the provider is contracted with; the exact codes billed; H0015 or S9480 and the revenue code and form for each plan; whether Humana, UnitedHealthcare and WellCare use the weekly rule; the IOP schedule and how attendance times are recorded; current authorizations and continued-stay handling; telehealth rules; rates and deadlines; which non-clinical services are billable; licensure; whether UnitedHealthcare is Medicaid or commercial; systems and AR history; the 42 CFR Part 2 consent and BAA; who signs off clinical appeals."
  ],
  compare:{title:"Kentucky IOP minimums (state standard, cited by Aetna and Passport)",head:["Population","Minimum per week"],rows:[["Adults (18 and over)","At least 3 hours a day, on at least 3 days, and at least 9 hours in the week"],["Adolescents (under 18)","At least 6 hours, on at least 2 days"]]},
  terms:[["Rolling seven-day week","Any seven consecutive days starting on the first IOP date of service on the claim."],["Weekly bundled codes","Codes such as H0020 and H0047 that cover a week; H0015 may not be billed outside them (Passport)."],["Recoupment","A payer taking back money already paid after a review finds the rules were not met."]],
  tips:["A week that starts on a Wednesday ends on the following Tuesday: build the claim on the dates, not the calendar week.","If a patient attends only two days in a week, check the plan’s rule before billing: under the adult minimum the claim may deny."],
  remember:"Kentucky IOP (Aetna, Passport): one claim per rolling 7-day week, statement dates = the week, a line and a unit per day. Adults 3 hours × 3 days, 9 hours; adolescents 6 hours, 2 days. Bill after the week, every note signed. Other plans: confirm.",
  see:[["spec","bh-iop"],["spec","bh-ub04"],["spec","bh-ky"]],
  source:SRC_KY}
]}
]});

/* Assessment questions: t = module short. Each wrong option carries its own "why not" (whyNot, in order). */
const Q=[
/* BH basics */
{t:"BH basics",q:"A patient has both depression and an alcohol use disorder. This is called:",correct:"A dual diagnosis (co-occurring disorders)",wrongs:["A partial hospitalization","A level 3 admission","A crisis intervention"],whyNot:["Partial hospitalization is a level of care, not a combination of conditions.","Level 3 is residential treatment, a level of care.","Crisis intervention is a type of service."],ex:"A mental health condition plus a substance use disorder in the same patient is a dual diagnosis."},
{t:"BH basics",q:"An intensive outpatient program (IOP) is which ASAM level of care?",correct:"Level 2.1",wrongs:["Level 1","Level 2.5","Level 3"],whyNot:["Level 1 is ordinary outpatient: short visits once or twice a week.","Level 2.5 is partial hospitalization, more hours than IOP.","Level 3 is residential, with an overnight stay."],ex:"ASAM levels: 1 outpatient, 2.1 IOP, 2.5 partial hospitalization, 3 and up residential."},
{t:"BH basics",q:"Which document proves the daily hours an IOP day needs?",correct:"The group note and attendance record with start and stop times",wrongs:["The discharge summary","The intake assessment","The authorization letter"],whyNot:["The discharge summary closes the episode; it does not prove a day’s hours.","The intake shows the diagnosis and starts the authorization.","The authorization approves days; it does not prove attendance."],ex:"Attendance with start and stop times is the proof that a day met the minimum hours."},
{t:"BH basics",q:"Partial hospitalization (PHP) compared with IOP:",correct:"Is a higher level of care, billed differently from IOP",wrongs:["Is the same thing under another name","Is a lower level than IOP","Always requires an overnight stay"],whyNot:["PHP is ASAM level 2.5; IOP is 2.1, with different codes.","PHP has more hours than IOP.","Overnight stays are residential, level 3 and up."],ex:"PHP uses H0035 and revenue codes 0912 or 0913; it is never used for IOP."},
{t:"BH basics",q:"An associate clinician (for example an LCSWA) provides therapy. Billing usually:",correct:"Goes under a supervisor, with the supervision documented, as each payer allows",wrongs:["Goes under any licensed clinician in the practice","Is never allowed","Goes under the associate’s own NPI with no conditions"],whyNot:["A claim is never billed under someone who did not supervise or render the service.","Many payers allow it under a supervisor.","Associates are still in training; payers set supervision rules."],ex:"Associates and interns may need to bill under a supervisor; confirm the rule per payer."},
{t:"BH basics",q:"42 CFR Part 2 protects:",correct:"Substance use treatment records, with stronger rules than HIPAA",wrongs:["Only psychotherapy notes","Billing company contracts","Medicare claims data"],whyNot:["Part 2 is about substance use treatment records, not only therapy notes.","Contracts with billing companies are BAAs under HIPAA.","Part 2 covers SUD records regardless of payer."],ex:"Substance use records are shared only with proper written consent; the updated rule’s compliance date was 16 February 2026."},
{t:"BH basics",q:"A program coordinates a patient’s MAT but does not prescribe. Who bills for the medicine management?",correct:"Whoever prescribes the medicine",wrongs:["The IOP program, on its per diem","The case manager","Nobody; MAT is never billed"],whyNot:["Coordinating MAT is not prescribing it; the per diem does not include the prescriber’s service.","Case management is a separate service.","MAT is billed, by the prescriber."],ex:"Medication-assisted treatment combines counseling with medicines; the prescriber bills for the medicine management."},
{t:"BH basics",q:"A therapist will be credentialed with the plan next month. Today’s session:",correct:"Cannot be billed under that therapist to that plan",wrongs:["Can be billed under any credentialed clinician","Can be billed and appealed later","Can be billed if the note is signed"],whyNot:["Never bill under someone who did not render the service.","Billing a non-credentialed provider is a compliance problem, not an appeal.","A signed note does not make the clinician credentialed."],ex:"A clinician must be credentialed with the payer on the date of service."},
{t:"BH basics",q:"Supportive housing offered by a behavioral health client is usually:",correct:"Non-clinical and not billable to insurance unless a covered benefit is documented",wrongs:["Billed as IOP","Billed as residential treatment","Billed as case management"],whyNot:["Housing is not a clinical program day.","Residential treatment is a licensed level of care, not housing.","Case management is a clinical support service with its own codes."],ex:"Treat housing as not billable unless the client documents a specific covered benefit."},
/* BH codes */
{t:"BH codes",q:"A psychotherapy session lasted 53 minutes. The code is:",correct:"90837",wrongs:["90834","90832","90853"],whyNot:["90834 is 38–52 minutes.","90832 is 16–37 minutes.","90853 is group therapy."],ex:"Psychotherapy is coded by documented time: 90832, 90834, 90837 for 53 minutes or more."},
{t:"BH codes",q:"How is EMDR billed?",correct:"With the psychotherapy code that matches the session length",wrongs:["With 90884","With its own CPT code","With H0015"],whyNot:["90884 is not used for EMDR without the payer’s confirmation.","There is no CPT code for EMDR.","H0015 is the SUD IOP per diem."],ex:"EMDR is billed as ordinary psychotherapy: 90832, 90834 or 90837."},
{t:"BH codes",q:"Who chooses the diagnosis code on a behavioral claim?",correct:"The clinician, in the documentation; the biller copies it",wrongs:["The biller, from the service billed","The payer","The front desk at intake"],whyNot:["Billers never assign or change a diagnosis.","The payer reviews it; it does not choose it.","The diagnosis comes from the clinician’s assessment."],ex:"Rule one of behavioral coding: billers do not choose diagnoses."},
{t:"BH codes",q:"F11.20 is in which family?",correct:"Opioid use disorders",wrongs:["Alcohol use disorders","Major depression","PTSD"],whyNot:["Alcohol is F10.","Major depression is F32 and F33.","PTSD is F43.1."],ex:"F10 alcohol, F11 opioids, F12 cannabis, F14 cocaine."},
{t:"BH codes",q:"On a dual-diagnosis IOP claim, the first-listed diagnosis is:",correct:"The clinician’s documented principal diagnosis, following the payer’s rule",wrongs:["Always the substance use diagnosis","Always the mental health diagnosis","Whichever pays more"],whyNot:["Often the SUD, but some payers (Passport) describe it differently.","Not always; it depends on the documentation and the payer.","Choosing for payment is a compliance violation."],ex:"Use the clinician’s principal diagnosis and get each payer’s rule in writing."},
{t:"BH codes",q:"A telehealth session with the patient at home is reported with POS:",correct:"10",wrongs:["02","11","23"],whyNot:["02 is telehealth with the patient somewhere other than home.","11 is in person at the office.","23 is the emergency room."],ex:"POS 11 clinic, 10 telehealth at home, 02 telehealth elsewhere."},
{t:"BH codes",q:"Passport by Molina’s telehealth rule for behavioral services is:",correct:"Modifier 95 (audio-video) or 93 (audio-only), with POS 02 or 10",wrongs:["Modifier GT with POS 11","Any telehealth modifier","No modifier, POS 02 only"],whyNot:["GT is not accepted by Passport, and POS 11 is in person.","Passport accepts no other telehealth modifiers.","Passport requires 95 or 93."],ex:"Telehealth modifiers vary by payer; a POS and modifier mismatch is a common denial."},
{t:"BH codes",q:"H0020 means:",correct:"Methadone administration or service",wrongs:["General medication management","Peer support","SUD group counseling"],whyNot:["It is not general medication management; do not use it for MAT coordination.","Peer support is H0038.","SUD group counseling is H0005."],ex:"Do not use H0020 for MAT coordination without the payer’s confirmation."},
{t:"BH codes",q:"Modifier HO on a behavioral service means:",correct:"Master’s-level clinician",wrongs:["Adult program","Opioid treatment program","Audio-only telehealth"],whyNot:["Adult program is HB.","Opioid treatment program is HG.","Audio-only is 93."],ex:"HO master’s, HN bachelor’s, HF substance abuse program, HG opioid program, HA child or adolescent, HB adult; only when the payer requires them."},
{t:"BH codes",q:"An alcohol and drug assessment billed with H0001 is:",correct:"Not the same service as a psychiatric diagnostic evaluation (90791)",wrongs:["The same as 90791","An IOP per diem","Peer support"],whyNot:["90791 is a psychiatric diagnostic evaluation; H0001 is an SUD assessment.","The IOP per diem is H0015 or S9480.","Peer support is H0038."],ex:"Confirm which assessment code each payer expects."},
{t:"BH codes",q:"Psychotherapy add-on codes 90833, 90836 and 90838 are billed:",correct:"By a prescriber, with an E/M visit",wrongs:["By any therapist on their own","Only on IOP days","Only for group therapy"],whyNot:["They are add-ons to an E/M code, which therapists do not bill.","On IOP days individual therapy is inside the per diem.","Group therapy is 90853."],ex:"A prescriber who also does an E/M visit adds the psychotherapy add-on by time."},
/* IOP billing */
{t:"IOP billing",q:"An IOP day is billed as:",correct:"One per diem unit covering all the services that day",wrongs:["One unit per hour of therapy","Separate codes for each group and individual session","One unit per week"],whyNot:["IOP is not billed by the hour.","The per diem bundles the day’s sessions.","The unit is the day; some plans want a weekly claim, but each day is still a unit."],ex:"Per diem means for each day: one unit per qualifying day."},
{t:"IOP billing",q:"Which code is the mental health IOP per diem?",correct:"S9480",wrongs:["H0015","H0035","90853"],whyNot:["H0015 is the SUD or co-occurring IOP per diem.","H0035 is partial hospitalization.","90853 is group psychotherapy."],ex:"S9480 mental health IOP; H0015 SUD or co-occurring IOP."},
{t:"IOP billing",q:"Revenue code 0906 on a UB-04 means:",correct:"Intensive outpatient, chemical dependency",wrongs:["Intensive outpatient, psychiatric","Partial hospitalization","Psychiatric rehabilitation"],whyNot:["Psychiatric IOP is 0905.","Partial hospitalization is 0912 or 0913.","0907 is a community behavioral health program (day treatment); no IOP code is psychiatric rehab."],ex:"0905 psychiatric IOP, 0906 chemical dependency IOP."},
{t:"IOP billing",q:"Which pairing of HCPCS and revenue code is always correct for H0015?",correct:"None is always correct: the pairing is set by each payer",wrongs:["H0015 always with 0906","H0015 always with 0905","H0015 always with 0912"],whyNot:["Common, but Passport pays H0015 under 0905.","Some payers want 0906.","0912 is partial hospitalization."],ex:"Do not hard-code the pairing; follow each payer’s IOP policy."},
{t:"IOP billing",q:"A therapist bills 90834 for a patient on a day the patient also attended IOP. The usual result:",correct:"Denied as duplicate or unbundled: individual therapy is part of the per diem",wrongs:["Paid in addition to the per diem","Paid instead of the per diem","Paid at half rate"],whyNot:["The per diem includes individual therapy.","The per diem is still billed for the day; the session is the problem.","There is no half-rate rule for this."],ex:"Therapy, group, family, crisis and psychoeducation are not billed separately on an IOP day."},
{t:"IOP billing",q:"Where does the IOP prior authorization number go on the UB-04?",correct:"Form locator 63 (treatment authorization code)",wrongs:["Form locator 44","Form locator 4","Form locator 80"],whyNot:["FL 44 holds the HCPCS code and modifiers.","FL 4 is the type of bill.","FL 80 is remarks."],ex:"FL 63 is the treatment authorization code."},
{t:"IOP billing",q:"One training sheet calls H0015 a “G code”. That is:",correct:"Wrong: H0015 is a HCPCS H code",wrongs:["Right: all IOP codes are G codes","Right for Medicare only","Right for Medicaid only"],whyNot:["IOP per diems are H and S codes.","Medicare does not pay H0015 as a G code.","Medicaid uses H0015 as an H code."],ex:"H codes are behavioral and SUD services; S codes are temporary codes some payers use."},
{t:"IOP billing",q:"Revenue code 0912 or 0913 on an IOP claim:",correct:"Is wrong: those are partial hospitalization",wrongs:["Is right for SUD IOP","Is right for adolescent IOP","Is right for telehealth IOP"],whyNot:["SUD IOP is usually 0906.","Age changes modifiers, not the level of care.","Telehealth changes POS and modifiers."],ex:"PHP is a different level of care: H0035, revenue codes 0912 and 0913."},
{t:"IOP billing",q:"Medicare IOP at an RHC or FQHC uses:",correct:"Revenue code 0905 with condition code 92",wrongs:["Revenue code 0900","Revenue code 0906 with S9480","Revenue code 0519 for every claim"],whyNot:["0900 is for a mental health visit without IOP.","Medicare does not pay S9480.","0519 is for the FQHC Medicare Advantage wrap-around."],ex:"CR 13264: 0905 + condition code 92 + at least one List A code."},
{t:"IOP billing",q:"An RHC billing Medicare IOP adds which modifier to the payment line?",correct:"CG",wrongs:["HB","95","PO"],whyNot:["HB marks an adult program on some Medicaid plans.","95 marks audio-video telehealth.","PO marks an excepted off-campus hospital department."],ex:"RHCs report CG so coinsurance is calculated; FQHCs report all charges on the primary line."},
{t:"IOP billing",q:"Medicare’s IOP plan of care must certify the patient needs at least:",correct:"9 hours of IOP services a week",wrongs:["20 hours a week","3 hours a week","5 days a week"],whyNot:["20 hours a week is partial hospitalization territory.","3 hours a day, not a week, is a common daily minimum.","Medicare certifies hours, not a fixed number of days."],ex:"Physician-certified plan, recertified no later than day 60 and then every 60 days."},
{t:"IOP billing",q:"On the same day, a patient has Medicare IOP and a mental health visit at an FQHC. Medicare pays:",correct:"One payment, at the IOP rate; the mental health visit is included",wrongs:["Both, separately","Only the mental health visit","Neither; same-day visits deny"],whyNot:["Both are paid only when the second visit is medical.","The IOP rate is the payment.","Same-day visits are paid by the rule, not denied."],ex:"IOP + medical visit: both paid. IOP + mental health visit: one IOP payment."},
{t:"IOP billing",q:"Does Medicare pay S9480?",correct:"No: Medicare does not pay S codes; Medicare IOP uses 0905 or 0906 with its own service codes",wrongs:["Yes, since 2024","Yes, for RHCs only","Yes, with modifier CG"],whyNot:["Medicare’s 2024 IOP benefit did not adopt S9480; one training sheet says otherwise.","RHCs bill 0905 + condition code 92 with List A codes.","CG is the RHC coinsurance modifier, not a way to bill S codes."],ex:"S codes are temporary codes used by commercial plans and Medicaid."},
/* BH payers and AR */
{t:"BH payers and AR",q:"An IOP authorization ends Friday; the patient continues next week. You:",correct:"Request a continued stay before it expires, with clinical updates",wrongs:["Bill next week and appeal if denied","Wait for the denial","Start a new authorization as an initial request after it expires"],whyNot:["Billing outside the authorization is a hard rule violation.","Waiting guarantees unpaid days.","Continuity is a continued-stay request, sent before expiry."],ex:"Request a continued stay several days to a week ahead; track used against approved days weekly."},
{t:"BH payers and AR",q:"An authorization packet for IOP usually includes:",correct:"The assessment, the ASAM assessment and level-of-care justification, and the treatment plan",wrongs:["Only the patient’s ID card","The previous month’s claims","The discharge summary"],whyNot:["The card proves coverage, not medical necessity.","Claims do not show the need for the level of care.","Discharge comes at the end of treatment."],ex:"Aetna requires the clinical record, the ASAM assessment and the treatment plan with the request."},
{t:"BH payers and AR",q:"Which is the hard rule for authorizations?",correct:"Never submit a claim whose date, code, units, provider or level of care falls outside the authorization",wrongs:["Bill first and request the authorization later","Bill the full week whatever the units approved","Use another patient’s authorization for the same program"],whyNot:["Authorizations come before services for IOP.","Units beyond approval deny as exceeded.","Authorizations are patient-specific."],ex:"Authorization is the highest revenue risk on a behavioral health account."},
{t:"BH payers and AR",q:"An IOP day was delivered by video. The hours count toward the weekly minimum:",correct:"Only if the plan allows telehealth IOP",wrongs:["Always","Never","Only if audio-only"],whyNot:["Some plans do not count telehealth hours.","Some plans, such as Passport, allow telehealth IOP.","Audio-only is often more restricted, not less."],ex:"Confirm per plan before scheduling telehealth IOP days."},
{t:"BH payers and AR",q:"An IOP claim denies as duplicate. The first thing to look for is:",correct:"A therapy, crisis or other per diem code billed on the same date",wrongs:["A missing referral","A wrong patient address","A missing taxonomy code"],whyNot:["Referral issues deny as no referral, not duplicate.","Address problems do not cause duplicate denials.","Taxonomy problems deny as provider-related."],ex:"Session codes on an IOP day are part of the per diem."},
{t:"BH payers and AR",q:"In AR cleanup, after pulling the aged trial balance, you next:",correct:"Segregate claims by denial reason",wrongs:["Call every payer in alphabetical order","Write off claims over 90 days","Resubmit every open claim"],whyNot:["Prioritize high-dollar and high-volume payers, and check portals before calling.","Old claims are worked first, not written off.","Blind resubmissions create duplicates."],ex:"Segregate by reason, prioritize the big payers, check portals, batch corrected claims."},
{t:"BH payers and AR",q:"Behavioral denials should be worked within:",correct:"24 to 48 hours",wrongs:["30 days","Before the appeal deadline only","The next monthly review"],whyNot:["Thirty days loses time against filing and appeal limits.","Waiting for the deadline leaves no room for a records request.","Monthly reviews are for trends, not working denials."],ex:"Log every denial with its root cause and whether it was preventable."},
{t:"BH payers and AR",q:"A medical-necessity appeal for denied IOP days needs:",correct:"The ASAM assessment, the treatment plan and the attendance for the denied days",wrongs:["Only a letter asking for payment","The patient’s billing statement","A copy of the ID card"],whyNot:["An appeal needs clinical evidence.","The statement shows money owed, not necessity.","The card proves coverage, not necessity."],ex:"Appeal with clinical records and the payer’s policy."},
/* Kentucky IOP */
{t:"Kentucky IOP",q:"Which plan left Kentucky Medicaid managed care on 1 January 2025?",correct:"Anthem",wrongs:["Passport by Molina","Aetna Better Health of Kentucky","WellCare of Kentucky"],whyNot:["Passport is an active Kentucky Medicaid plan.","Aetna Better Health is an active plan.","WellCare is an active plan."],ex:"A patient showing an Anthem Medicaid card needs a fresh eligibility check."},
{t:"Kentucky IOP",q:"Kentucky fee-for-service Medicaid claims are processed by:",correct:"Gainwell Technologies",wrongs:["Optum","Each MCO in turn","Medicare"],whyNot:["Optum handles UnitedHealthcare behavioral health authorizations.","FFS members are not in an MCO.","Medicare is a separate program."],ex:"Check FFS versus MCO for every date of service."},
{t:"Kentucky IOP",q:"Under Aetna and Passport, an IOP week is billed as:",correct:"One claim for a rolling seven-day period starting on the first IOP date of service",wrongs:["One claim per day","One claim per calendar week, Sunday to Saturday","One claim per month"],whyNot:["Billing daily is exactly what the weekly rule forbids.","The week is rolling, not tied to Sunday.","A claim may not span more than seven days."],ex:"Statement from and through dates must match the seven-day period."},
{t:"Kentucky IOP",q:"A Kentucky adult IOP week needs at least:",correct:"3 hours a day, on 3 days, and 9 hours in the week",wrongs:["6 hours over 2 days","1 hour a day, 5 days","20 hours a week"],whyNot:["6 hours over 2 days is the adolescent minimum.","IOP days need about 3 hours each.","20 hours is partial hospitalization level."],ex:"Adolescents: at least 6 hours on at least 2 days."},
{t:"Kentucky IOP",q:"The IOP week started on a Wednesday. The claim’s through date is:",correct:"The following Tuesday",wrongs:["The Saturday of the same week","The Sunday after","The end of the month"],whyNot:["The week is rolling, not the calendar week.","Seven days from Wednesday ends on Tuesday.","Monthly claims are not allowed under the weekly rule."],ex:"The week starts on the first date of service on the claim and runs seven consecutive days."},
{t:"Kentucky IOP",q:"Passport allows an evaluation (90791) on an IOP day:",correct:"Only outside IOP hours, not duplicative and documented as necessary",wrongs:["Never","Always, in addition to the per diem","Only by telehealth"],whyNot:["Passport allows a narrow exception.","It is not routinely payable with the per diem.","Telehealth is not the condition; timing and documentation are."],ex:"Targeted case management (T2023) has the same outside-IOP-hours exception on Passport."},
{t:"Kentucky IOP",q:"Since 25 June 2025, Kentucky Medicaid plans require authorization for IOP:",correct:"At all five MCOs (S9480, H0015, revenue codes 0905 and 0906)",wrongs:["At none of them","Only at Passport","Only for adolescents"],whyNot:["House Bill 695 reinstated behavioral authorization rules.","The state grid shows it at all five plans.","Authorization applies to adults and adolescents."],ex:"Kentucky HB 695 (2025) reinstated the authorization rules of 1 January 2020."},
{t:"Kentucky IOP",q:"Aetna Better Health of Kentucky’s timely filing limit for an initial claim is:",correct:"365 days from the date of service",wrongs:["90 days","180 days","24 months"],whyNot:["90 days is shorter than Aetna’s Kentucky limit.","180 days is not Aetna’s Kentucky limit.","24 months is Aetna’s window for corrected claims, from the remittance."],ex:"Appeals with Aetna: 60 days from the notification."},
{t:"Kentucky IOP",q:"Which proof of timely filing has Passport accepted?",correct:"Fax confirmation or a signed postal receipt",wrongs:["Any clearinghouse report, always","A screenshot of the billing system","The patient’s statement"],whyNot:["Whether a clearinghouse acceptance counts is an open question to confirm.","A system screenshot is not proof the payer received it.","Patient statements prove nothing about submission."],ex:"Ask Passport whether a clearinghouse acceptance report is also accepted."},
{t:"Kentucky IOP",q:"An item in the Kentucky guide is marked CONFIRM. You:",correct:"Ask the lead and get it in writing; never guess it",wrongs:["Use the most common rule","Use another plan’s rule","Bill and see what happens"],whyNot:["Common is not confirmed for this payer.","Each plan has its own rules.","Guessing creates denials and recoupments."],ex:"Do not apply one MCO’s rule to another; the payer’s contract controls."}
];
Q.forEach(x=>{ x.c="bh"; SPEC_QUIZ.push(x); });
})();
